import * as core from "@actions/core";
// State variables needed for setup-docker-builder
export const tmpDir = process.env.STATE_tmpDir || "";
export const inputs = process.env.STATE_inputs
    ? JSON.parse(process.env.STATE_inputs)
    : undefined;
export function setTmpDir(tmpDir) {
    core.saveState("tmpDir", tmpDir);
}
export function setInputs(inputs) {
    core.saveState("inputs", JSON.stringify(inputs));
}
export function setExposeId(exposeId) {
    core.saveState("exposeId", exposeId);
}
export function getExposeId() {
    return core.getState("exposeId");
}
// Reason the host gave at mount time for denying this job's sticky disk
// commit (e.g. branch protection); empty when no denial was reported.
export function setCommitEarlyDenyReason(reason) {
    core.saveState("commitEarlyDenyReason", reason);
}
export function getCommitEarlyDenyReason() {
    return core.getState("commitEarlyDenyReason");
}
// Host-supplied budget, in whole seconds, for trimming the sticky disk before
// unmount at commit; 0 when the host has not enabled the trim.
export function setFstrimTimeoutSecs(secs) {
    core.saveState("fstrimTimeoutSecs", String(secs));
}
export function getFstrimTimeoutSecs() {
    const secs = Number(core.getState("fstrimTimeoutSecs") || "0");
    return Number.isFinite(secs) && secs > 0 ? Math.floor(secs) : 0;
}
export function setFstrimMinExtentBytes(bytes) {
    core.saveState("fstrimMinExtentBytes", String(bytes));
}
export function getFstrimMinExtentBytes() {
    const n = Number(core.getState("fstrimMinExtentBytes") || "0");
    return Number.isFinite(n) && n > 0 ? Math.floor(n) : 0;
}
export function setBuildkitdAddr(addr) {
    core.saveState("buildkitdAddr", addr);
}
export function getBuildkitdAddr() {
    return core.getState("buildkitdAddr");
}
export function setBuilderName(name) {
    core.saveState("builderName", name);
}
export function getBuilderName() {
    return core.getState("builderName");
}
export function setCacheKey(key) {
    core.saveState("cacheKey", key);
}
export function getCacheKey() {
    return core.getState("cacheKey");
}
// Builder lifecycle facts recorded in the main step and read back in the
// post step for the docker-build teardown report.
export function setBuilderMode(mode) {
    core.saveState("builderMode", mode);
}
export function getBuilderMode() {
    return core.getState("builderMode");
}
export function setFallbackReason(reason) {
    core.saveState("fallbackReason", reason);
}
export function getFallbackReason() {
    return core.getState("fallbackReason");
}
export function setHotloadDurationMs(ms) {
    core.saveState("hotloadDurationMs", ms.toString());
}
export function getHotloadDurationMs() {
    return parseInt(core.getState("hotloadDurationMs"), 10) || 0;
}
export function setBuildkitdReadyDurationMs(ms) {
    core.saveState("buildkitdReadyDurationMs", ms.toString());
}
export function getBuildkitdReadyDurationMs() {
    return parseInt(core.getState("buildkitdReadyDurationMs"), 10) || 0;
}
let _sigkillUsed = false;
export function setSigkillUsed(used) {
    _sigkillUsed = used;
    core.saveState("sigkillUsed", used.toString());
}
export function getSigkillUsed() {
    return _sigkillUsed || core.getState("sigkillUsed") === "true";
}
